	currentNode.Handle("poll", s.handlePoll)
	currentNode.Handle("commit_offsets", s.handleCommit)
	currentNode.Handle("list_committed_offsets", s.handleListCommitted)

	if err := currentNode.Run(); err != nil {
		log.Fatal(err)
	}
}

